<script setup lang="ts">
definePageMeta({ middleware: 'sanctum:auth', layout: 'account' })
const route = useRoute(); const orderStore = useOrderStore(); const toast = useToast()
const { data: order, pending, refresh } = await useAsyncData(`order-${route.params.id}`, () => orderStore.fetchOrder(String(route.params.id)))
const cancel = async () => { if (!order.value) return; try { await orderStore.cancelOrder(order.value.id); toast.add({ title: 'Commande annulée', color: 'success' }); await refresh() } catch(e:any){ toast.add({ title: 'Annulation impossible', description: e?.data?.message || e?.message, color: 'error' }) } }
</script>
<template><div class="font-syne"><div v-if="pending" class="rounded-3xl bg-white p-6">Chargement...</div><div v-else-if="order" class="space-y-6"><div class="rounded-3xl bg-white p-6 border border-black/5 shadow-sm"><div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4"><div><p class="font-mono text-xs uppercase opacity-50">Commande</p><h1 class="text-3xl font-black">{{ order.order_number }}</h1></div><div class="text-right"><p class="text-2xl font-black">{{ formatPrice(order.total) }}</p><p class="font-mono text-xs uppercase opacity-60">{{ order.status }} · {{ order.payment_status }}</p></div></div></div><section class="rounded-3xl bg-white p-6 border border-black/5 shadow-sm"><h2 class="text-xl font-black uppercase">Articles</h2><div class="mt-4 divide-y"><div v-for="item in order.items" :key="item.id" class="py-4 flex justify-between gap-4"><div><p class="font-bold">{{ item.product_name }}</p><p class="font-mono text-xs opacity-50">Qté {{ item.quantity }}</p></div><p class="font-mono">{{ formatPrice(item.total || item.price * item.quantity) }}</p></div></div></section><section class="rounded-3xl bg-white p-6 border border-black/5 shadow-sm"><h2 class="text-xl font-black uppercase">Livraison</h2><p class="mt-3 opacity-70">{{ order.shipping_address?.first_name }} {{ order.shipping_address?.last_name }} · {{ order.shipping_address?.phone }}</p><p class="opacity-70">{{ order.shipping_address?.address_line1 }}, {{ order.shipping_address?.city }}</p></section><div class="flex gap-3"><a v-if="order.payment_url" :href="order.payment_url" class="rounded-full bg-[#0066bf] px-5 py-3 text-white font-bold">Payer maintenant</a><button v-if="['pending','confirmed'].includes(order.status)" @click="cancel" class="rounded-full border border-red-500 px-5 py-3 text-red-600 font-bold">Annuler</button></div></div></div></template>
